def split_even_odd(lst):
    """偶数索引(0,2,4..)的元素进 even，奇数索引(1,3,5..)的进 odd。
    返回 (even, odd) 两个列表。"""
    even = []
    odd = []
    for i in range(len(lst)):
        if i % 2 == 0:
            even.append(lst[i])
        else:
            odd.append(lst[i])
    return even, odd
